import feal, random
f=feal.f_function
# search input diffs with byte values in {0,0x80} for constant output diff
cands=[]
for b in range(256):
    d=0
    for i in range(4):
        if b>>i & 1: d |= 0x80 << (8*i)
    outs=set()
    for t in range(300):
        x=random.getrandbits(32)
        outs.add(f(x)^f(x^d))
    if len(outs)==1: cands.append((hex(d),hex(outs.pop())))
print(cands)
"

